    // is still needed to report how many copies were submitted.
    if (existing) existing.quantity += entry.quantity;
    else byCard.set(entry.row.oracle_id, { row: entry.row, quantity: entry.quantity });
  }

  let ignoredCopies = 0;
  const result: OwnedCard[] = [];

